新增：
export function dispersion_change(old_mean:number, old_var:number, new_mean:number, new_var:number):number {
  if (![old_mean,old_var,new_mean,new_var].every(Number.isFinite)) {
    throw new RangeError('dispersion_change requires finite inputs');
  }
  if (old_mean <= 0 || new_mean <= 0 || old_var < 0 || new_var < 0) return -1;
  const oldD=old_var/old_mean;
  const newD=new_var/new_mean;
  if (!Number.isFinite(oldD) || !Number.isFinite(newD)) {
    throw new RangeError('dispersion ratio overflow; rescale or use higher precision');
  }
  return Math.max(-1000000,Math.min(1000000,newD-oldD));
}

新增候选叶宽函数：
function blade_half_width_r5b(t:number, base:number, clipped:boolean):number {
  const u=Math.max(0,Math.min(1,t));
  const tip=clipped ? 0.28 : 0.045;
  return base*(1-(1-tip)*u*u);
}

